    let isCardValidated: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(validatedCard),
      description: "validatedCard.oclIsUndefined()",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => this.CardIDValidated === false,
        description: "CardIDValidated=false",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l()
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsUndefined(validatedCard),
            description: "validatedCard.oclIsUndefined()",
          }),
        description: "validatedCard.oclIsUndefined()",
        then: l({
          execute: () => (this.CardIDValidated = false),
          description: "CardIDValidated=false",
        }),
        else: l({
          execute: () => (this.CardIDValidated = true),
          description: "CardIDValidated=true",
        }).and({
          execute: () => (this.InputCard = validatedCard),
          description: "InputCard=validatedCard",
        }),
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

